interface ApiRequestScope {
  profile: string | null
  connectionId: string | null
}

export interface OwnerScope {
  connectionId?: null | string
  profile?: null | string
}

export interface ResolvedOwner {
  connectionId: null | string
  profile: null | string
}

export interface SessionReadOwnerRoute {
  connectionId?: null | string
  profile?: null | string
  targetProfile?: null | string
}

export interface DelegationProfileRoute {
  name: string
  description?: string
}

export interface DelegationModelMap {
  options: DelegationModelRoute[]
  default: null | string
}

export interface DelegationProfileRoutes {
  profiles: DelegationProfileRoute[]
  default: null | string
}

export interface DelegationRouting {
  /** The saved `delegation.backend` (normalized; `default` when unset). */
  configured: string
  /** Why the saved backend cannot run here (plugin missing, off or unavailable); `null` when it runs.
   *  Core fails closed: while this is set every subagent is refused, it never quietly runs Default. */
  blocked_reason: null | string
  backends: DelegationBackendInfo[]
  model_map: DelegationModelMap
  profile_routes: DelegationProfileRoutes
  /** Profiles of this backend host a profile route may name. */
  profiles: string[]
}

export interface LocalModelsScope {
  connectionId: string | null
  profile: string
}

export interface HFFileGroup {
  label: string
  paths: string[]
  total_bytes: number
  fit: 'fits-gpu' | 'needs-ram' | 'too-big' | 'unknown'
}

export interface McpTestResult {
  ok: boolean
  error?: string
  /** `schema_chars` (converted registry-schema size, chars) is additive —
   *  older backends omit it and the cost overlay shows no token estimate. */
  tools: { name: string; description: string; schema_chars?: number }[]
  /** Capability counts (absent on older backends / failed probes). */
  prompts?: number
  resources?: number
}

export interface MessagingPlatformUpdateResponse {
  hot_served?: boolean
  ok: boolean
  platform: string
}

export interface RecommendedDefaultModel {
  provider: string
  model: string
  /** True/false for Nous (free vs paid tier); null for other providers. */
  free_tier: boolean | null
}

export interface PluginRestOptions {
  method?: string
  body?: unknown
  /** Single-file multipart upload (see HermesApiRequest.upload). */
  upload?: { filename: string; contentType?: string; bytes: ArrayBuffer }
  timeoutMs?: number
}

export interface SessionSourceFilter {
  source?: string
  excludeSources?: string[]
}

export interface SidebarSessionSlice {
  sessions: SessionInfo[]
  /** Per-profile "the window came back full, more rows exist on disk" flags —
   *  what pagination needs, without a COUNT(*) per profile DB per refresh. */
  profiles_truncated?: Record<string, boolean>
  /** Per-profile tokens and spend over every session, not just this window.
   *  Absent from the legacy per-slice endpoint, which has no aggregate. */
  profiles_usage?: Record<string, { cost_usd: number; tokens: number }>
  /** This slice is a failed load, not a successful empty session list. */
  failed?: boolean
  /** Ask the sidebar to offer Retry instead of rendering "No sessions yet". */
  retry?: boolean
  /** Profiles whose scan failed while a sibling profile still returned rows. */
  profiles_failed?: Record<string, { failed?: boolean; retry?: boolean; error?: string }>
  /** Profiles whose scan for THIS slice failed. Batched `/sidebar` stamps the
   *  same profile errors on every slice (one DB open). Legacy per-slice calls
   *  stamp only the slice that actually failed, so a cron I/O error cannot
   *  carry-forward recents. */
  errors?: Array<{ profile: string; error: string }>
}

export interface SidebarSessionsResponse {
  recents: SidebarSessionSlice
  cron: SidebarSessionSlice
  messaging: SidebarSessionSlice
  errors?: Array<{ profile: string; error: string }>
  /** Profiles that failed while another profile's rows are still in the slices. */
  profiles_failed?: Record<string, { failed?: boolean; retry?: boolean; error?: string }>
  /** `{profile: 'corrupt'}` for each profile whose state.db the backend has found
   *  structurally damaged. Absent from older backends. */
  storage?: Record<string, 'corrupt'>
}

export interface LearningNodeDetail {
  content: string
  kind: 'memory' | 'skill'
  label: string
  ok: boolean
}

export interface SelectToolsetProviderResponse {
  ok: boolean
  name: string
  provider: string
  /** Present when the selection was scoped to one web capability. */
  capability?: string
  /** Present (true) when a managed Nous row was selected but the Portal
   *  entitlement is missing — the row won't activate until the user signs
   *  in to Nous Portal. */
  needs_nous_auth?: boolean
  /** The managed feature key (e.g. "browser") when needs_nous_auth is set. */
  feature?: string
}

interface AgentsViewProps {
  onClose: () => void
}

interface RootGroup {
  id: string
  delegationIndex: number
  nodes: SubagentNode[]
  taskCount: number
}

export interface ArtifactLoadFailure {
  error: unknown
  session: SessionInfo
}

export interface ArtifactLoadResult {
  artifacts: ArtifactRecord[]
  failures: ArtifactLoadFailure[]
}

type CellCtx = {
  onOpen: (artifact: ArtifactRecord) => void | Promise<void>
  onOpenChat: (sessionId: string) => void
}

interface ArtifactsViewProps extends React.ComponentProps<'section'> {
  setStatusbarItemGroup?: SetStatusbarItemGroup
}

interface ArtifactImageCardProps {
  artifact: ArtifactRecord
  failedImage: boolean
  onImageError: (id: string) => void
  onOpenChat: (sessionId: string) => void
}

interface CatalogAddButtonProps {
  name: string
  installed: boolean
  installing: boolean
  disabled: boolean
  onInstall: () => void
  /** Hero cards and the detail have room: "+ Install" instead of a bare +. */
  labeled?: boolean
}

interface CatalogDetailDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  /** On-screen order to page through; wraps at both ends. */
  order: CatalogEntry[]
  selectedId: string
  onSelect: (id: string) => void
  children: ReactNode
}

export interface FacetRow {
  value: string
  label: string
