}

export type AccountEdit =
  | { connectionId: string; draft?: string; error?: string; kind: 'rename' }
  | {
      draft?: string
      error?: string
      kind: 'add'
    }

export interface AddServerDialogProps {
  controller: McpServersController
  onOpenChange: (open: boolean) => void
  open: boolean
  profile: ProfileScope
}

export interface DraftValue {
  id: number
  value: string
}

export interface DraftPair {
  id: number
  key: string
  value: string
}

export interface AddServerFormProps {
  draft: AddServerDraft
  nameTaken: boolean
  onChange: (next: AddServerDraft) => void
}

export interface CategoryPickerProps {
  categories: CountedValue[]
  onChange: (category: null | string) => void
  value: null | string
}

export interface ConnectElementProps {
  operation: AccountOperation
  /** Restarts the failed sign-in of the account the operation is for; absent while one is still waiting. */
  onRetry?: () => void
  onStopWaiting: () => void
  /** A start for this app is in flight; a second Try again would mint a second replacement sign-in. */
  retrying?: boolean
}

interface LeadVerb {
  busy?: boolean
  run: () => void
  verb: ConnectorVerb
}

export interface ConnectorsTabProps {
  gateway: HermesGateway | null
  profile: ProfileScope
}

export interface AccountOperationRequest {
  alias?: string
  connectionId?: string
  reconnect: boolean
}

export interface HostedActions {
  busySlug: null | string
  connectAccount: (card: ConnectorCardModel, reconnect: boolean, address?: ConnectAddress) => Promise<ConnectOutcome>
  connector: ConnectorConnect
  remover: AccountDisconnect
  /** Runs a failed sign-in's own request again, so it mints a fresh link for the same account. */
  retry: (card: ConnectorCardModel, operation: AccountOperation) => void
  /** Runs a hosted card's verb; false when the verb is not a hosted one (a local server's). */
  runHostedVerb: (card: ConnectorCardModel) => boolean
  startConnect: (card: ConnectorCardModel, reconnect: boolean, account?: AccountRow) => Promise<void>
  switcher: ConnectorSwitch
  write: (pending: Promise<WriteOutcome>) => Promise<void>
}

export interface HostedActionOptions {
  /** Runs after a sign-in starts. */
  onStarted?: (card: ConnectorCardModel) => void
  /** Where the browser's return shows the user; the Connectors page when absent. */
  returnRoute?: string
}

export interface ConnectorPolicyTagRules {
