}

export interface ConnectOptions {
  /** The account's name: a new account takes it; with `reconnect`, only that account is repaired. */
  alias?: string
  /** With `reconnect`, the existing account to repair; the only address an unnamed account has. */
  connectionId?: string
  reconnect?: boolean
  /** Where the browser's return shows the user; the Connectors page when absent. */
  returnRoute?: string
}

export interface ConnectorConnect {
  connect: (slug: string, options?: ConnectOptions) => Promise<ConnectOutcome>
  giveUp: (opId: string) => Promise<WriteOutcome>
  pending: null | string
}

interface PersistedEntry {
