interface ControlProps {
  field: PluginSettingField
  id: string
  raw: string
  disabled: boolean
  onChange: (raw: string) => void
  /** Localised hint for a secret that already has a stored value. */
  secretSetHint: string
}

interface ScopeOption {
  key: string
  label: string
  value: string
}

export interface CapabilityScope {
  /** Which profile's Skills/Tools/MCP config every tab reads and writes — and
   *  on WHICH gateway. */
  profile: ProfileScope
  /** Cache-key form of `profile`: every scoped query key ends with it, and the
   *  tabs are keyed on it so a scope change is a fresh tab. */
  key: string
  /** Scoped to a DIFFERENT backend than the window's active gateway? The MCP
   *  tab's live-reload RPC rides the active gateway socket, which would reload
   *  the wrong machine — it is withheld for cross-backend scopes. */
  crossBackend: boolean
  /** Display name of the selected profile (the Plugins tab's Agent column). */
  label?: string
  options: ScopeOption[]
  value: string
  onChange: (value: string) => void
}

interface SkillsTabProps {
  /** The scope's skill list, straight from the shell's query. */
  skills: SkillInfo[]
  /** Every read and write targets this connection/profile pair. */
  profile: ProfileScope
  query: string
  onQueryChange?: (value: string) => void
  installedPending?: boolean
  installedError?: unknown
  onRefresh: () => void
}

interface ToolsetsTabProps {
  /** The scope's toolset list, straight from the shell's query. */
  toolsets: ToolsetInfo[]
  /** The (connection, profile) scope every read and write routes to. */
  profile: ProfileScope
  query: string
  onQueryChange: (query: string) => void
  /** Data-derived "Try …" placeholder nudges. */
  hints?: string[]
}

export interface CatalogSurfaceItem {
  id: string
  name: string
  description: string
  /** Topline label: who or what the item belongs to. */
  eyebrow?: string
  /** Footer badge: the one piece of meta the item carries. */
  badge?: string
  action?: ReactNode
  onOpen: () => void
}

export interface CatalogSurfaceSection {
  id: string
  label: string
  blurb?: string
  /** `feature` is the tall-card row; `list` is the two-up small-banner list. */
  layout: 'feature' | 'list'
  items: CatalogSurfaceItem[]
}

interface ShowChatBarOptions {
  loadingSession: boolean
  resumeExhausted: boolean
  routedSessionId: null | string
  routedSessionView: boolean
}

export interface BusySubmitState {
  busyAction: ComposerBusyAction
  canSteer: boolean
  canSubmit: boolean
}

export interface TriggerAcceptInput {
  /** The user moved the highlight themselves (arrow keys) rather than
   *  inheriting the list's default first row. */
  activeExplicit: boolean
  /** The trigger is a slash command whose argument is arbitrary prose. */
  freeTextArgStage: boolean
  key: string
  kind: TriggerState['kind']
  query: string
}

export interface QueueEditState {
  attachments: ComposerAttachment[]
  draft: string
  entryId: string
  sessionKey: string
}

export interface PendingDraftPersist {
  scope: string | null
  text: string
}

interface ContextMenuItemProps {
  children: string
  disabled?: boolean
  icon: IconComponent
  onSelect?: () => void
}

interface PromptSnippetsDialogProps {
  onInsertText: (text: string) => void
  onOpenChange: (open: boolean) => void
  open: boolean
}

export interface ComposerDraft {
  text: string
  attachments?: ComposerAttachment[]
}

export interface ComposerMiddleware {
  /** Rewrite (return a draft), pass through (same draft), or cancel (null). */
  handler: (draft: ComposerDraft) => ComposerDraft | null | Promise<ComposerDraft | null>
}

export interface ComposerAtCompletionItem {
  /** Text inserted into the draft when picked (e.g. `@researcher`). */
  insert: string
  /** Row label; defaults to `insert`. */
  display?: string
  /** Secondary line (e.g. "Bot · Homelab"). */
  meta?: string
  /** Icon slug understood by the completion popover; defaults to 'simple'. */
  icon?: string
  /** Other `@handle` texts that resolve to the SAME target as `insert` —
   *  e.g. a bot's raw profile name alongside the title slug it is listed
   *  under. The `@` popover drops a gateway row whose handle is claimed
   *  here, so one routable identity is never offered twice under two
   *  labels. Only claim handles this row really owns. */
  handles?: string[]
}

export interface ComposerAtCompletionSource {
  provide: (query: string) => ComposerAtCompletionItem[]
}

export interface ComposerAttachmentContext {
  insertText: (text: string) => void
}

export interface ComposerAttachmentProvider {
  label: string
  /** Codicon name for the menu row. Defaults to `plug`. */
  icon?: string
  run: (ctx: ComposerAttachmentContext) => void | Promise<void>
}

export interface ComposerMicroActionProvider {
  resolve: (ctx: ComposerMicroActionContext) => ComposerAction[]
}

export interface ComposerMicroActionContext {
  /** A turn is currently running in this session. */
  busy: boolean
  sessionId: string
  /** Live todo list for the session (empty when there is none). */
  todos: readonly TodoItem[]
}

export interface ComposerModelPillContext {
  /** The model slug the pill would show. */
  model: string
  /** The session's live reasoning effort ('' when the model has none). */
  reasoningEffort: string
  /** Floating-composer mode renders only the chevron; providers are not consulted. */
  compact: boolean
}

export interface ComposerModelPillProvider {
  label: (ctx: ComposerModelPillContext) => null | string
}

export interface FloatingComposerOwner {
  id: string
  groupId: string
  target: ComposerTarget
}

interface ComposerSurfaceProps {
  children: ReactNode
}

export interface FocusDetail {
  target: ComposerTarget
  /** Append after focus (type-to-focus / soft `/`). */
  typeChar?: string
}

interface InsertDetail {
  mode: ComposerInsertMode
  target: ComposerTarget
  text: string
  /** Present when the caller wants an acknowledgement (plugin SDK
   *  `host.composer.insertText`); the claiming subscriber echoes it back on
   *  {@link INSERT_REPLY_EVENT}. Internal fire-and-forget inserts omit it. */
  token?: number
}

interface InsertRefsDetail {
  refs: InlineRefInput[]
  target: ComposerTarget
}

interface InsertReplyDetail {
  ok: boolean
  token: number
}

interface AttachImagesDetail {
  blobs: Blob[]
  target: ComposerTarget
}

interface SubmitDetail {
  /** Unique mounted composer surface captured at click time. */
  surfaceId: string
  target: ComposerTarget
  text: string
  /** `hidden` types the persisted user row so no bubble renders — the
   *  off-screen path for widget intents. Omit for normal visible sends. */
  displayKind?: 'hidden'
}

export interface DraftRequestDetail {
  token: number
  ids: string[]
  active?: boolean
  /** Set-draft payload; absent on read requests. */
  text?: string
  /** Stamped by the first owning surface so a second owner of the same id
   *  (the primary pane plus a keep-alive tile showing that session) skips it. */
  claimed?: boolean
}

interface DraftReplyDetail {
  ids?: string[]
  ok?: boolean
  text?: null | string
  token: number
}

interface AtItemMetadata extends Record<string, string> {
  icon: string
  display: string
  meta: string
  /** Raw `text` field from the gateway, e.g. `@file:src/main.tsx` or `@diff`. */
  rawText: string
  /** Just the value portion (after `@kind:`), or empty for simple refs. */
  insertId: string
}

interface AutoSpeakReply {
  id: string
  pending: boolean
  text: string
  /** Text that identifies this message within its turn: the bubble's last text
   *  part. Hydration folds a tool-call turn into one bubble whose full text
   *  changes, but whose last text part is still this message. Defaults to `text`. */
  segmentText?: string
  /** Survives the live-id rewrite. Absent callers still speak; they just cannot join an in-flight play. */
  turnKey?: string
}

interface UseAutoSpeakReplies {
  conversationActive: boolean
  failureLabel: string
  /** Mark the current last reply spoken — shared dedupe with the conversation consumer. */
  markSpoken: () => void
  /** Latest completed assistant reply, or null; `pending` true while still streaming. */
  pendingReply: () => AutoSpeakReply | null
  /** Re-arm on session switch so opening a chat never reads its existing last reply. */
  sessionId: string | null | undefined
}

interface UseComposerBranchOptions {
  clearDraft: () => void
  cwd: null | string | undefined
  draftRef: MutableRefObject<string>
}

interface UseComposerEscCancelOptions {
  awaitingInput: boolean
  busy: boolean
  onCancel: () => unknown
  /** This composer's focus-bus key. With N composers mounted (main + tiles),
   *  only the active one's Esc cancels — otherwise every busy tile stops. */
  target: ComposerTarget
}

export interface ComposerFit {
  compactPill: boolean
  foldVoice: boolean
  minimal: boolean
  tight: boolean
}

interface UseComposerMetricsResult extends ComposerFit {
  stacked: boolean
}

interface UseComposerPlaceholderOptions {
  disabled: boolean
  reconnecting: boolean
  sessionId: null | string | undefined
}

interface UseComposerPopoutOptions {
  composerRef: RefObject<HTMLFormElement | null>
}

interface ScreenshotComposerOptions {
  sessionKey: string | null
  focusKey?: string | null
  onAttachImageBlob: ChatBarProps['onAttachImageBlob']
}

interface CompletionSource {
  adapter: Unstable_TriggerAdapter | null
  loading: boolean
}

interface UseComposerTriggerOptions {
  at: CompletionSource
  draftRef: MutableRefObject<string>
  editorRef: RefObject<HTMLDivElement | null>
  /** `:joy` emoji completions — inserts the emoji character, never a chip. */
  emoji?: CompletionSource
  /** Bank the pre-commit state so a popover pick is a single undo step. */
  recordUndoPoint?: () => void
  requestMainFocus: () => void
  setComposerText: (text: string) => void
  slash: CompletionSource
}

interface UseComposerUndoArgs {
  editorRef: RefObject<HTMLDivElement | null>
  /** Push a restored snapshot back into draftRef + composer state. */
  syncDraftFromEditor: () => string
}

