export interface RpcMethods {
  /** Registry-wide background process summary for ``/agents``. */
  'agents.list': { params: AgentsListParams; result: AgentsListResult }
  /** Replay the approvals still waiting on this session (reconnect / polling). */
  'approval.pending': { params: ApprovalPendingParams; result: ApprovalPendingResult }
  /** Tell the backend the card is on screen, so its timeout clock starts. */
  'approval.received': { params: ApprovalReceivedParams; result: ApprovalReceivedResult }
  /** Deliver the user's decision on a dangerous command (falls back to durable identity on a stale sid). */
  'approval.respond': { params: ApprovalRespondParams; result: ApprovalRespondResult }
  /** Enable/disable auto top-up with its threshold and reload amount (billing:manage). */
  'billing.auto_reload': { params: BillingAutoReloadParams; result: BillingMutationResult }
  /** Start a one-off top-up charge (billing:manage, idempotent). */
  'billing.charge': { params: BillingChargeParams; result: BillingChargeResult }
  /** Poll one charge by id. */
  'billing.charge_status': { params: BillingChargeStatusParams; result: BillingChargeStatusResult }
  /** Window plans: turn 'Keep going on credits' on/off (billing:manage). */
  'billing.keep_going_on_credits': { params: BillingKeepGoingOnCreditsParams; result: BillingMutationResult }
  /** Read-only billing view (no scope); the Nous free tier is answered locally without a portal call. */
  'billing.state': { params: ProfileParams; result: BillingStateResult }
  /** Run the billing:manage device flow; the URL/code arrive via billing.step_up.verification. */
  'billing.step_up': { params: BillingStepUpParams; result: BillingStepUpResult }
  /** Deliver a relayed DM into a Bot Chat on this gateway and return the one-turn reply (blocking). */
  'bot_relay.deliver': { params: BotRelayDeliverParams; result: BotRelayDeliverResult }
  /** Atomically claim every pending cross-connection envelope queued on this gateway. */
  'bot_relay.outbox.drain': { params: BotRelayOutboxDrainParams; result: BotRelayOutboxDrainResult }
  /** Write a relayed reply and/or typed error for an envelope so the sender-side waiter resolves. */
  'bot_relay.reply': { params: BotRelayReplyParams; result: OkResult }
  /** Replace this gateway's view of agents on other connections; answers the accepted row count. */
  'bot_relay.roster.sync': { params: BotRelayRosterSyncParams; result: BotRelayRosterSyncResult }
  /** Hard-detach only the controller owned by this authenticated transport. */
  'browser.controller.detach': { params: BrowserControllerParams; result: BrowserControllerDetachResult }
  /** Acknowledge a heartbeat only for this transport's own attached controller. */
  'browser.controller.heartbeat': { params: BrowserControllerParams; result: OkResult }
  /** Attach this connection as the browser controller for one session; fails closed (4403). */
  'browser.controller.register': { params: BrowserControllerRegisterParams; result: BrowserControllerRegisterResult }
  /** Deliver one command result to the broker; accepted is false for unknown or settled command ids. */
  'browser.controller.result': { params: BrowserControllerResultParams; result: BrowserControllerResultResult }
  /** Inspect, attach to, or drop the CDP browser the tools use, or switch Browser Use mode (``use``, applies to new sessions); ``messages`` narrate a connect. */
  'browser.manage': { params: BrowserManageParams; result: BrowserManageResult }
  /** Lock one answer of a batch clarify request (editable until every question is locked). */
  'clarify.lock': { params: ClarifyLockParams; result: ClarifyLockResult }
  /** Run ``hermes <argv>`` non-interactively and capture its output; ``blocked`` explains a refusal. */
  'cli.exec': { params: CliExecParams; result: CliExecResult }
  /** What the calling client handles, sent once per connection (after gateway.ready); returns the server→client request methods this backend may send. */
  'client.capabilities': { params: ClientCapabilitiesParams; result: ClientCapabilitiesResult }
  /** Save the host clipboard image into the session and queue it for the next turn. */
  'clipboard.paste': { params: ClipboardPasteParams; result: AttachedImageResult }
  /** Run a quick/plugin/bundle/skill/built-in slash command and answer a structured directive. */
  'command.dispatch': { params: CommandDispatchParams; result: CommandDispatchResult }
  /** Canonical registry command for a name or alias. */
  'command.resolve': { params: CommandResolveParams; result: CommandResolveResult }
  /** Categorized slash metadata (registry, quick, plugin, skill) for completion menus. */
  'commands.catalog': { params: CommandsCatalogParams; result: CommandsCatalogResult }
  /** Path / @-reference completions for the composer (files, folders, profiles, plugin providers). */
  'complete.path': { params: CompletePathParams; result: CompletionItemsResult }
  /** Ranked slash-command / skill completions for a ``/`` token. */
  'complete.slash': { params: CompleteSlashParams; result: CompleteSlashResult }
  /** Read one normalised config value (or the whole effective config) the way the UIs render it. */
  'config.get': { params: ConfigGetParams; result: ConfigGetResult }
  /** Change one config key (persisted or session-scoped) and read back the normalised value. */
  'config.set': { params: ConfigSetParams; result: ConfigSetResult }
  /** Masked, display-ready config summary (model / agent / environment rows). */
  'config.show': { params: ConfigShowParams; result: ConfigShowResult }
  /** Per-target outcomes from the card, and an optional Continue. */
  'connection.respond': { params: ConnectionRespondParams; result: ConnectionRespondResult }
  /** The scoped member's hosted connector accounts, optionally filtered by connector slug. */
  'connectors.accounts': { params: ConnectorAccountsParams; result: ConnectorAccountsResult }
  /** Remove one hosted connector account owned by the scoped member. */
  'connectors.accounts.remove': { params: ConnectorAccountsRemoveParams; result: ConnectorAccountsRemoveResult }
  /** Name or rename one hosted connector account owned by the scoped member. */
  'connectors.accounts.rename': { params: ConnectorAccountsRenameParams; result: ConnectorAccountRow }
  /** The hosted connector catalog available to the scoped member. */
  'connectors.catalog': { params: ProfileParams; result: ConnectorsCatalogResult }
  /** Start or re-initiate authorization for named connectors on a session or account operation. */
  'connectors.connect': { params: ConnectorsConnectParams; result: ConnectorsConnectResult }
  /** Connector catalog + connection state for one session or profile account owner. */
  'connectors.list': { params: ConnectorsListParams; result: ConnectorsListResult }
  /** The current snapshot of one open session or account operation. */
  'connectors.operation.status': { params: ConnectionOperationParams; result: ConnectionOperationStatus }
  /** The browser leg came back (hermes://connections/done): read the accounts now, not at the next tick. */
  'connectors.operation.wake': { params: ConnectionOperationParams; result: ConnectionWakeResult }
  /** Policy layers for the scoped member, from organization to member scope. */
  'connectors.policy.get': { params: ProfileParams; result: ConnectorPolicyGetResult }
  /** Apply one scoped member connector or tool-list policy change. */
  'connectors.policy.set': { params: ConnectorPolicySetParams; result: ConnectorPolicySetResult }
  /** The scoped profile's cached or current tool list for one connector. */
  'connectors.tools': { params: ConnectorToolsParams; result: ConnectorToolsResult }
  /** List/add/remove/pause/resume cron jobs in the (optionally profile-scoped) cron store. */
  'cron.manage': { params: CronManageParams; result: CronManageResult }
  /** Block/unblock NEW spawns globally (active children keep running); returns the new state. */
  'delegation.pause': { params: DelegationPauseParams; result: DelegationPauseResult }
  /** Running subagent tree plus the spawn pause flag and limits. */
  'delegation.status': { params: ProfileParams; result: DelegationStatusResult }
  /** Upload a force-redacted debug bundle to Nous-internal diagnostics storage. */
  'diagnostics.share_nous': { params: DiagnosticsShareNousParams; result: DiagnosticsShareNousResult }
  /** Run the distro package install on the gateway host; progress streams as display.install.log/.done. */
  'display.install': { params: ProfileParams; result: DisplayInstallResult }
  /** Take over: the human named by a viewer id this connection minted controls the screen. */
  'display.lease.acquire': { params: DisplayLeaseAcquireParams; result: DisplayLeaseResult }
  /** Hand back. Without a viewer id the release is refused while a human holds unless force. */
  'display.lease.release': { params: DisplayLeaseReleaseParams; result: DisplayLeaseResult }
  /** Mint a single-use ticket for /api/display/ws and the server-minted viewer id for this connection. */
  'display.observe': { params: DisplayObserveParams; result: DisplayObserveResult }
  /** Start this profile's Xvnc + Xfce (idempotent); blocks until the display is published. */
  'display.start': { params: ProfileParams; result: DisplayStatus }
  /** Runtime + lease snapshot for this profile's screen. */
  'display.status': { params: ProfileParams; result: DisplayStatus }
  /** Stop the screen. Refused (5300, code viewer_mismatch) while a human holds unless force. */
  'display.stop': { params: DisplayStopParams; result: DisplayStopResult }
  /** Decide the pending default sandbox image switch for this profile; refused when none is pending. */
  'display.switchSandboxImage': { params: DisplaySwitchSandboxImageParams; result: DisplaySwitchSandboxImageResult }
  /** One JPEG grab of the bot's screen; read-only, never changes the lease. */
  'display.thumbnail': { params: ProfileParams; result: DisplayThumbnailResult }
  /** Stage a non-image file into the session workspace and hand back its @file: ref. */
  'file.attach': { params: FileAttachParams; result: FileAttachResult }
  /** Mark the one-time availability notice as shown on the free-tier identity. */
  'free_tier.ack_notice': { params: ProfileParams; result: FreeTierAckNoticeResult }
