  /** Argument text with the outer whitespace removed; interior kept verbatim. */
  arg: string
  /** Lower-cased command name without the slash; '' for `/`, `/   `, `/ words`. */
  name: string
}

export interface ExecCommandDispatchResponse {
  output?: string
  type: 'exec' | 'plugin'
}

export interface AliasCommandDispatchResponse {
  target: string
  type: 'alias'
}

export interface SkillCommandDispatchResponse {
  /** The invocation the UI renders (`/work fix the leak`). `message` is the
   *  expanded skill body — model-facing scaffolding no surface may show. */
  display?: string
  message?: string
  name: string
  type: 'skill'
}

export interface SendCommandDispatchResponse {
  /** Set for a skill-bundle send: see SkillCommandDispatchResponse.display. */
  display?: string
  message: string
  notice?: string
  type: 'send'
}

export interface PrefillCommandDispatchResponse {
  message: string
  notice?: string
  type: 'prefill'
}

export interface ThemePresetPalette {
  /** Light palette (also reused for dark when `darkColors` is omitted). */
  colors: ThemePresetColors
  /** Hand-tuned dark palette. Skins like `nous` ship one. */
  darkColors?: ThemePresetColors
}

export interface TranslucencyBook {
  mode: TranslucencyMode
  base: Partial<TranslucencyValues>
  light: Partial<TranslucencyValues>
  dark: Partial<TranslucencyValues>
}

export interface UpdateDebtStep {
  step: string
  reason?: string | null
}

export interface UpdateDebtReceipt {
  outcome?: string | null
  action_id?: string | null
  followups?: UpdateDebtStep[] | null
  user_action?: UpdateDebtStep | null
}

export interface UpdateDebt {
  /** Follow-ups a rerun of `hermes update` finishes, as `step (reason); step`; '' when none. */
  followups: string
  /** What only the user can do (e.g. re-apply a parked stash) as `step: <producer's instruction>`;
   *  '' when none. Never phrase this as "re-run hermes update": a rerun does not restore it. */
  userAction: string
}

export interface GatewayWsConnection {
  authMode?: GatewayAuthMode | null
  profile?: null | string
  wsUrl: string
}

export interface ResolveGatewayWsUrlDeps {
  /**
   * Returns a fresh WebSocket URL for the selected backend/profile.
   * OAuth-gated gateways use single-use tickets, so callers should mint
   * immediately before opening the socket.
   */
  getGatewayWsUrl?: (profile?: null | string) => Promise<GatewayWsUrlResult>
}

export type GatewayWsUrlResult =
  | string
  | { ok: true; wsUrl: string }
  | { error: string; needsOauthLogin?: boolean; ok: false }

export interface HermesWebSocketUrlOptions {
  /** Dashboard or gateway-relative endpoint path, e.g. "/api/ws". */
  path: string
  /** Optional URL prefix when the backend is reverse-proxied below a subpath. */
  basePath?: string
  /** Query auth pair, usually ["token", value] or ["ticket", value]. */
  authParam?: WebSocketAuthParam
  /** Extra query params merged before auth. */
  params?: Record<string, string>
  /** Browser protocol string such as "https:"; defaults to window.location.protocol. */
  protocol?: string
  /** Host with optional port; defaults to window.location.host. */
  host?: string
}
